xpath.script:
(function () {
    var t = null;
    try { t = localStorage.getItem("vela-theme"); } catch (e) {}
    if (t !== "dark" && t !== "light") {
        t = window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches ? "dark" : "light";
    }
    document.documentElement.setAttribute("data-vela-theme", t);
})();
